 const [f,setF]=useState(()=>{if(!initial)return {...emptyTrade};const legacy=initial.lots==null||initial.lot_size==null;return {...emptyTrade,...initial,quantity:String(initial.quantity??''),lots:String(legacy?'1':initial.lots),lot_size:String(legacy?defaultLotSize(initial.instrument):initial.lot_size),option_type:initial.option_type||'CE',strike_price:initial.strike_price??''}}),[busy,setBusy]=useState(false),[file,setFile]=useState(null);
